export const title = "How to Choose a Desk Clock That Is Readable Without Dominating a Bedroom";
export const metaTitle = "How to Choose a Readable Bedroom Desk Clock";
export const metaDescription = "Compare a desk clock by actual viewing distance, display controls, power behavior, alarm access, and placement in a shared small room.";
